## 2. The twelve implementations

### 2.1 `parser_grammar_io` — `check_rules` + `check_set` (robustness pass)

The only change from what was already written is the two empty-input guards. Without them an empty or malformed grammar file prints a bare header followed by a stray blank line, and the operator cannot tell "extraction produced nothing" from "extraction was not run".

```cpp
void check_rules(const vector<rule> rules) {
	//按提取顺序逐条输出文法规则
	cout << "提取文法规则：" << endl;
	if (rules.empty()) {
		//文法文件为空或者书写格式有误时给出提示，避免只打印一个空行
		cout << "    （未提取到任何文法规则，请检查文法文件的书写格式）" << endl << endl;
		return;
	}
	for (unsigned int i = 0; i < rules.size(); i++) {
		cout << "    " << rules[i] << endl;
	}
	cout << endl;
}
template <class T>
void check_set(set<T> set_, string tip) {
	//按集合内部的有序性依次输出各个元素
	cout << tip << "：" << endl;
	cout << "    ";
	if (set_.empty()) {
		//空集合同样给出提示，方便对照检查提取结果
		cout << "（空）" << endl << endl;
		return;
	}
	for (typename set<T>::iterator it = set_.begin(); it != set_.end(); it++) {
		if (it != set_.begin()) {
			cout << "  ";
		}
		cout << *it;
	}
	cout << endl << endl;
}
```

`typename` before `set<T>::iterator` is required in a template (dependent type) — omitting it is a hard error under `-std=c++11`. Elements are separated by two spaces with a four-space indent, matching the `提取规则右部：\n    @  Ab  aH  aM  aMd  d  e` output.

### 2.2 `parser_first_formatter` — `operator<<(ostream&, F_set)`

```cpp
ostream& operator << (ostream& out, F_set f_set) {
	//根据判别符区分两类集合，形如“First(右部)={a,b}”或者“Follow(非终结符)={#,a}”
	if (f_set.is_first) {
		out << "First(" << f_set.left << ")={";
	}
	else {
		out << "Follow(" << f_set.left << ")={";
	}
	//集合元素之间用逗号分隔
	for (set<char>::iterator it = f_set.right.begin(); it != f_set.right.end(); it++) {
		if (it != f_set.right.begin()) {
			out << ",";
		}
		out << *it;
	}
	out << "}";
	return out;
}
```

`f_set.left` is a `string` for FIRST (a whole right-hand side such as `aMd`) and a one-char string for FOLLOW — the struct's `string left` handles both, which is why `findFollow` must do `f_set.left = non_terminal;` (implicit `char` → `string` via `operator=`, valid) rather than any manual conversion.

### 2.3 `parser_first_core` — `findFirst` + its recursive helper

```cpp
//判断一个字符是否是非终结符：文法中凡是作为规则左部出现过的字符都是非终结符
static bool is_non_terminal(const char c, const vector<rule>& rules) {
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (rules[i].left == c) {
			return true;
		}
	}
	return false;
}
//求符号串ss的First集，visiting记录当前正在展开的非终结符，防止左递归文法导致无限递归
static set<char> firstOf(const string ss, const vector<rule>& rules, set<char>& visiting) {
	set<char> result;
	bool all_epsilon = true;//ss中的每个符号都能推出空串时，First集里才有“@”
	for (unsigned int i = 0; i < ss.length(); i++) {
		char c = ss[i];
		if (c == '@') {
			continue;//“@”本身就代表空串，不影响它后面的符号
		}
		if (!is_non_terminal(c, rules)) {
			result.insert(c);//终结符直接进入First集
			all_epsilon = false;
			break;//终结符后面的符号对First集不再有贡献
		}
		if (visiting.count(c) > 0) {
			all_epsilon = false;
			break;//该非终结符正处在展开过程中，再展开下去就会陷入死循环
		}
		//非终结符：把它的每一个候选式的First集并进来
		visiting.insert(c);
		bool has_epsilon = false;
		for (unsigned int j = 0; j < rules.size(); j++) {
			if (rules[j].left != c) {
				continue;
			}
			for (unsigned int k = 0; k < rules[j].right.size(); k++) {
				set<char> sub = firstOf(rules[j].right[k], rules, visiting);
				for (set<char>::iterator it = sub.begin(); it != sub.end(); it++) {
					if (*it == '@') {
						has_epsilon = true;//该候选式能推出空串，暂不收录“@”
					}
					else {
						result.insert(*it);
					}
				}
			}
		}
		visiting.erase(c);
		if (!has_epsilon) {
			all_epsilon = false;
			break;//该非终结符推不出空串，后面的符号对First集不再有贡献
		}
	}
	if (all_epsilon) {
		result.insert('@');//整个符号串都能推出空串
	}
	return result;
}
F_set findFirst(const string ss, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = true;
	f_set.left = ss;
	set<char> visiting;
	f_set.right = firstOf(ss, rules, visiting);
	return f_set;
}
```

Key points: `@` is *skipped*, not inserted, during the scan — `@` only enters `result` at the very end via the `all_epsilon` flag, which is what makes `First(@)={@}` and `First(AB)={@,b,c}` (test2, both `A` and `B` nullable) come out right while `First(aMd)={a}` does not accidentally pick up `M`'s `@`. "Non-terminal" is defined as "appears as some rule's left part", *not* "is uppercase" — so a grammar using lowercase non-terminals still works, and an uppercase letter that has no production is treated as a terminal rather than silently vanishing.

### 2.4 `parser_first_sets` — `checkFirst`

```cpp
vector<F_set> checkFirst(set<string> right_parts, vector<rule> rules) {
	//逐个求出各条规则右部符号串的First集，重复的右部在set里已经合并，只会显示一次
	vector<F_set> f_sets;
	cout << "各规则右部的First集：" << endl;
	for (set<string>::iterator it = right_parts.begin(); it != right_parts.end(); it++) {
		F_set f_set = findFirst(*it, rules);
		cout << "    " << f_set << endl;
		f_sets.push_back(f_set);
	}
	cout << endl;
	return f_sets;
}
```

The spec's "重复的只需展示 1 次" is satisfied for free because `right_parts` is a `set<string>` filled by `split_into_rules`. Iteration is lexicographic, so test3 prints `@, Ab, aH, aM, aMd, d, e` (`@`=0x40 before uppercase `A`=0x41 before lowercase).

### 2.5 `parser_follow_core` — `findFollow` + its recursive helper

```cpp
//求非终结符的Follow集，visiting记录当前正在求Follow集的非终结符，防止规则相互引用导致无限递归
static set<char> followOf(const char non_terminal, const vector<rule>& rules, set<char>& visiting) {
	set<char> result;
	result.insert('#');//“#”是输入串的结束标志，任何非终结符的Follow集里都带上它
	visiting.insert(non_terminal);
	for (unsigned int i = 0; i < rules.size(); i++) {
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			const string& part = rules[i].right[j];
			//同一个候选式中该非终结符可能出现多次，逐个位置考察
			string::size_type pos = part.find(non_terminal);
			while (pos != string::npos) {
				bool at_end = true;//其后的符号串是否能推出空串（出现在末尾时同样成立）
				if (pos + 1 < part.length()) {
					//紧跟其后的符号串的First集去掉“@”之后并入Follow集
					set<char> visiting_first;
					set<char> first = firstOf(part.substr(pos + 1), rules, visiting_first);
					at_end = false;
					for (set<char>::iterator it = first.begin(); it != first.end(); it++) {
						if (*it == '@') {
							at_end = true;//后继符号串能推出空串，还要并入规则左部的Follow集
						}
						else {
							result.insert(*it);
						}
					}
				}
				if (at_end && visiting.count(rules[i].left) == 0) {
					//位于规则末尾时，规则左部的Follow集整个并入
					set<char> parent = followOf(rules[i].left, rules, visiting);
					result.insert(parent.begin(), parent.end());
				}
				pos = part.find(non_terminal, pos + 1);
			}
		}
	}
	visiting.erase(non_terminal);
	return result;
}
F_set findFollow(const char non_terminal, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = false;
	f_set.left = non_terminal;
	set<char> visiting;
	f_set.right = followOf(non_terminal, rules, visiting);
	return f_set;
}
```

Three details worth flagging. **(a)** The FIRST recursion gets its *own* fresh `visiting_first` — the two guards track different things (which non-terminals are mid-FIRST-expansion vs mid-FOLLOW-computation) and sharing one set would spuriously prune. **(b)** The `while (pos != npos)` loop handles a non-terminal occurring more than once in the same candidate (`A::=BaB`). **(c)** `at_end` starts `true` so the `pos + 1 == part.length()` case (occurrence in final position) falls straight into the parent-FOLLOW merge without evaluating an empty suffix.

### 2.6 `parser_follow_sets` — `checkFollow`

```cpp
vector<F_set> checkFollow(set<char> non_terminal, vector<rule> rules) {
	//逐个求出各个非终结符的Follow集
	vector<F_set> f_sets;
	cout << "各非终结符的Follow集：" << endl;
	for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
		F_set f_set = findFollow(*it, rules);
		cout << "    " << f_set << endl;
		f_sets.push_back(f_set);
	}
	cout << endl;
	return f_sets;
}
```

Iteration is over the `set<char>`, so the *display* order is alphabetical (`A, E, H, M` for test3) — which is fine and expected here, and is deliberately **not** the order used for `table.row` (Q2).

### 2.7 `parser_ll1_header` — first half of `LL_1()`

```cpp
LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules) {
	LL_1_table table;
	//行表头：按规则书写的先后顺序排列非终结符，这样第一行对应的就是文法的开始符号
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (find(table.row.begin(), table.row.end(), rules[i].left) == table.row.end()) {
			table.row.push_back(rules[i].left);
		}
	}
	//只出现在右部、没有产生式的非终结符同样占一行，避免分析表缺行
	for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
		if (find(table.row.begin(), table.row.end(), *it) == table.row.end()) {
			table.row.push_back(*it);
		}
	}
	//列表头：全部终结符再加上输入串的结束标志“#”，“#”固定放在最后一列
	terminal.insert('#');
	for (set<char>::iterator it = terminal.begin(); it != terminal.end(); it++) {
		if (*it != '#' && *it != '@') {
			table.col.push_back(*it);
		}
	}
	table.col.push_back('#');
	//表中每个单元格先放一条空规则，能填入产生式的单元格随后再覆盖
	rule blank;
	blank.left = 0;
	table.rules.assign(table.row.size() * table.col.size(), blank);
```

`#` must be *skipped* during the sorted walk and *appended* afterwards: `'#'` is 0x23, so a naive walk would put it in the **first** column (`#abde`) and the unit test demands `abde#`. `'@'` is filtered defensively — `split_into_rules` already excludes it from `terminal`, but the guard costs nothing and documents the intent. The `terminal.insert('#')` mutates the caller's set through the reference; that is harmless here because `main()` calls `check_set(terminal, ...)` *before* `LL_1(...)`, so the printed terminal list stays free of `#`. Worth a comment if anyone ever reorders `main()`. `find` needs `<algorithm>`, already included at line 8.

### 2.8 `parser_ll1_builder` — second half of `LL_1()`

```cpp
	//逐条候选式填表：候选式的First集里有哪个终结符，就把它填到对应的单元格里
	for (unsigned int i = 0; i < rules.size(); i++) {
		//行号由规则左部决定
		vector<char>::iterator row_it = find(table.row.begin(), table.row.end(), rules[i].left);
		if (row_it == table.row.end()) {
			continue;
		}
		unsigned int r = (unsigned int)(row_it - table.row.begin());
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			//单元格里存放的是“左部::=某一个候选式”这样一条单候选式规则
			rule cell;
			cell.left = rules[i].left;
			cell.right.push_back(rules[i].right[j]);

			F_set first = findFirst(rules[i].right[j], rules);
			set<char> heads = first.right;
			//候选式能推出空串时，改用左部的Follow集来决定填表的位置
			if (heads.count('@') > 0) {
				F_set follow = findFollow(rules[i].left, rules);
				heads.insert(follow.right.begin(), follow.right.end());
			}
			for (set<char>::iterator it = heads.begin(); it != heads.end(); it++) {
				if (*it == '@') {
					continue;//“@”自身不是终结符，不占分析表的列
				}
				vector<char>::iterator col_it = find(table.col.begin(), table.col.end(), *it);
				if (col_it == table.col.end()) {
					continue;
				}
				unsigned int c = (unsigned int)(col_it - table.col.begin());
				table.rules[r * table.col.size() + c] = cell;
			}
		}
	}
	return table;
}
```

The critical design point: each cell stores a **single-candidate** `rule` (`cell.right` has exactly one element), never the multi-candidate rule from the grammar. That is what makes `operator<<` print `H::=aMd` in cell `[H,a]` and `H::=d` in cell `[H,d]` rather than `H::=aMd|d` in both, and it is what lets the parse loop do `rule_temp.right[0]` unambiguously. Note also that the FIRST-derived columns are *not* replaced by the FOLLOW columns when a production is nullable — `heads` is a union, though for a literal `@` candidate FIRST is just `{@}` so only FOLLOW contributes.

### 2.9 `parser_ll1_table` — `operator<<(ostream&, LL_1_table)`

```cpp
ostream& operator << (ostream& out, LL_1_table table) {
	out << "LL(1)分析表如下：" << endl;
	//列表头：第一列留给非终结符，其余各列依次对应一个终结符
	out << setw(8) << " ";
	for (unsigned int j = 0; j < table.col.size(); j++) {
		out << setw(12) << table.col[j];
	}
	out << endl;
	//逐行输出：行首是非终结符，其后是各个单元格里的产生式，空单元格留白
	for (unsigned int i = 0; i < table.row.size(); i++) {
		out << setw(8) << table.row[i];
		for (unsigned int j = 0; j < table.col.size(); j++) {
			ostringstream cell;
			unsigned int at = i * table.col.size() + j;
			if (at < table.rules.size() && !table.rules[at].right.empty()) {
				cell << table.rules[at];
			}
			out << setw(12) << cell.str();
		}
		out << endl;
	}
	out << endl;
	return out;
}
```

The `ostringstream cell` is mandatory, per Q5. The `at < table.rules.size()` bound check keeps a malformed table from reading out of range. Widths 8 and 12 are chosen so that the longest content actually produced — `E::=(T)` / `H::=aMd` / `D::=dBe` at 7 chars — leaves at least one space of gutter. A 3-character non-terminal on the left of a long production would need width 14; 12 is right for these grammars and matches the readme screenshots.

### 2.10 `parser_parse_state` — `print_state`

```cpp
void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
	//分析栈按“栈底到栈顶”的顺序输出，栈底的“#”排在最左边
	string analysis = "";
	while (!analysis_s.empty()) {
		analysis = string(1, analysis_s.top()) + analysis;
		analysis_s.pop();
	}
	//输入栈按“栈顶到栈底”的顺序输出，正好是剩余的输入串
	string input = "";
	while (!input_s.empty()) {
		input += input_s.top();
		input_s.pop();
	}
	//所用产生式：右部为空说明这一步不是推导而是终结符匹配
	ostringstream action;
	if (!rule_temp.right.empty()) {
		action << rule_temp;
	}
	else if (rule_temp.left != 0) {
		action << "“" << rule_temp.left << "”匹配";
	}
	cout << setw(20) << analysis << setw(20) << input << setw(20) << action.str() << endl;
}
```

Both stacks are taken **by value** — that is the whole trick, and it is why the signature is `stack<char>` and not `const stack<char>&`: the function destructively drains its private copies to read them, leaving the caller's stacks untouched. The two columns are built in *opposite* directions on purpose: the analysis stack is prepended (`top` ends up rightmost, so the display reads bottom→top and the sentinel `#` anchors the left edge, `#dbMa`), while the input stack is appended (`top` ends up leftmost, so the display is literally the remaining input, `abd#`). Both conventions match the lab screenshots.

### 2.11 `parser_analysis_init` — bootstrap half of `syntacticAnalysis()`

```cpp
void syntacticAnalysis(LL_1_table table) {
	cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
	string input;
	cin >> input;

	//分析栈：栈底压入结束标志“#”，其上压入文法的开始符号，即分析表的第一行
	stack<char> analysis_s;
	analysis_s.push('#');
	if (!table.row.empty()) {
		analysis_s.push(table.row[0]);
	}
	//输入栈：结束标志“#”压在栈底，待分析的字符串倒序入栈，栈顶就是当前输入符号
	stack<char> input_s;
	input_s.push('#');
	for (int i = (int)input.length() - 1; i >= 0; i--) {
		input_s.push(input[i]);
	}

	//分析是否成功的标志，一旦出现无法匹配或者查不到产生式的情况就置为false
	bool success = true;
	if (table.row.empty()) {
		cout << "没有可用的文法规则，无法进行语法分析" << endl;
		success = false;
	}

	//分析过程表头
	cout << endl << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(20) << "所用产生式" << endl;
```

The reverse push loop uses a **signed** `int i` because `i >= 0` on an `unsigned` would never terminate for an empty string — the classic bug. `cin >> input` skips leading whitespace and stops at the first whitespace, which is right for a token-free terminal string and works identically for the piped `printf 'aaabd\n'` the harness uses. If extraction fails (EOF / empty stdin) `input` stays empty and the loop below rejects cleanly via the empty-cell path; no special case needed.

### 2.12 `parser_analysis` — parse-loop half of `syntacticAnalysis()`

```cpp
	//表驱动的分析过程：栈顶是非终结符就查表展开，是终结符就与当前输入符号匹配
	rule rule_temp;//本步骤所用的产生式，右部为空表示该步骤只是一次终结符匹配
	rule_temp.left = 0;
	unsigned int step = 0;
	while (success) {
		char top = analysis_s.top();
		char cur = input_s.top();
		if (top == '#' && cur == '#') {
			//分析栈与输入串同时到达结束标志，分析成功结束
			rule_temp.left = 0;
			rule_temp.right.clear();
			print_state(analysis_s, input_s, rule_temp);
			break;
		}
		if (++step > 10000) {
			cout << "推导步骤过多，文法可能存在左递归，分析终止" << endl;
			success = false;
			break;
		}
		vector<char>::iterator row_it = find(table.row.begin(), table.row.end(), top);
		if (row_it == table.row.end()) {
			//栈顶是终结符：与当前输入符号相同才能一起弹出，否则分析失败
			if (top != cur) {
				cout << "栈顶终结符" << top << "与当前输入符号" << cur << "不匹配，分析终止" << endl;
				success = false;
				break;
			}
			rule_temp.left = top;
			rule_temp.right.clear();
			print_state(analysis_s, input_s, rule_temp);
			analysis_s.pop();
			input_s.pop();
			continue;
		}
		//栈顶是非终结符：用当前输入符号查分析表，取出对应的产生式
		vector<char>::iterator col_it = find(table.col.begin(), table.col.end(), cur);
		unsigned int at = 0;
		if (col_it != table.col.end()) {
			at = (unsigned int)(row_it - table.row.begin()) * table.col.size() + (unsigned int)(col_it - table.col.begin());
		}
		if (col_it == table.col.end() || at >= table.rules.size() || table.rules[at].right.empty()) {
			cout << "分析表中(" << top << "," << cur << ")处为空，分析终止" << endl;
			success = false;
			break;
		}
		rule_temp = table.rules[at];
		print_state(analysis_s, input_s, rule_temp);
		//用产生式右部替换栈顶的非终结符，右部为“@”时只弹出不压入
		analysis_s.pop();
		string right = rule_temp.right[0];
		if (right != "@") {
			//右部倒序入栈，保证最左边的符号处在栈顶
			for (int i = (int)right.length() - 1; i >= 0; i--) {
				analysis_s.push(right[i]);
			}
		}
	}

	cout << endl << "字符串" << input;
	if (!success) {
		cout << "不";
	}
	cout << "是该文法的句子" << endl;
}
```

Invariants: `analysis_s` and `input_s` both always retain their bottom `#`, so `top()` is never called on an empty stack — the `top == '#' && cur == '#'` accept test fires before either could drain. `print_state` is always called **before** mutating the stacks, so each row shows the *pre-step* configuration and the production about to be applied — the standard textbook trace layout. The `while (success)` condition plus explicit `break`s means every exit path has already set `success` correctly for the verdict line. Failure diagnostics print on their own line, un-`setw`'d, deliberately breaking the table to draw the eye — and the failing row is *not* printed, so the last table row is always the last *successful* step.

Three ways out, three distinct messages:

| condition | message |
|---|---|
| stack-top terminal ≠ lookahead | `栈顶终结符d与当前输入符号b不匹配，分析终止` |
| `[non-terminal, lookahead]` blank, or lookahead not a column (illegal char in input) | `分析表中(H,e)处为空，分析终止` |
| >10000 steps | `推导步骤过多，文法可能存在左递归，分析终止` |

The "lookahead not a column" case folds into the blank-cell message and is what catches an input string containing a character the grammar has never heard of.

